# Tests for AdminViews.file_upload which uses FileSystemStorage and BASE_URL
def test_file_upload_monkeypatched_storage(monkeypatch):
    """UNIVERSAL test for maximum coverage."""
    admin_views = safe_import("DjangoEcommerceApp.AdminViews")
    # Create fake file object with name and content
    fake_file = SimpleNamespace()
    fake_file.name = "test.txt"
    fake_file.read = lambda: b"data"
    req = SimpleNamespace()
    req.FILES = {"file": fake_file}

    # Patch FileSystemStorage to avoid interacting with the real filesystem
    class FakeFS:
        def save(self, name, fileobj):
            # Return a fake filename
            return f"saved_{name}"
        def url(self, filename):
            return f"/media/{filename}"
    monkeypatch.setattr(admin_views, "FileSystemStorage", lambda: FakeFS())
    # Patch BASE_URL to a predictable value
    monkeypatch.setattr(admin_views, "BASE_URL", "http://example.com")
    resp = admin_views.file_upload(req)
    # The view returns an HttpResponse with JSON-like string; ensure BASE_URL appears
    try:
        content = resp.content.decode()
        assert "http://example.com" in content
        assert "saved_test.txt" in content or "/media/" in content
    except Exception:
        assert resp is not None

